package br.com.elyon.audit;
import org.junit.jupiter.api.Test;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.test.web.servlet.MockMvc;import org.springframework.security.test.context.support.WithMockUser;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"APP_PASSWORD=test-password-123","spring.datasource.url=jdbc:h2:mem:testdb"}) @AutoConfigureMockMvc class WebTest {@Autowired MockMvc mvc;@Test void requiresLogin()throws Exception{mvc.perform(get("/")).andExpect(status().is3xxRedirection());}@Test @WithMockUser void rendersDashboard()throws Exception{mvc.perform(get("/")).andExpect(status().isOk()).andExpect(view().name("index")).andExpect(content().string(org.hamcrest.Matchers.containsString("name=\"username\""))).andExpect(content().string(org.hamcrest.Matchers.containsString("name=\"mode\" value=\"automatic\""))).andExpect(content().string(org.hamcrest.Matchers.containsString("id=\"loadingOverlay\""))).andExpect(content().string(org.hamcrest.Matchers.containsString("role=\"progressbar\""))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("name=\"segment\"")))).andExpect(content().string(org.hamcrest.Matchers.not(org.hamcrest.Matchers.containsString("name=\"evidence\""))));}@Test @WithMockUser void blocksMissingCsrf()throws Exception{mvc.perform(post("/analisar")).andExpect(status().isForbidden());}@Autowired AuditRepository repo;
@Test @WithMockUser void rendersStoredReport()throws Exception{Audit a=new Audit();a.username="teste";a.status="CONCLUÍDO";a.source="Teste";a.evidence="Bio informada";a.followerCount=1234L;a.followingCount=321L;a.report="{\"resumo\":\"Diagnóstico\",\"limitacoes\":[\"Sem métricas\"],\"recomendacoes\":[],\"bioProposta\":\"Bio proposta\",\"identidade\":\"Direção sugerida\",\"calendario\":[]}";repo.save(a);mvc.perform(get("/analises/"+a.id)).andExpect(status().isOk()).andExpect(view().name("detail")).andExpect(content().string(org.hamcrest.Matchers.containsString("Seguidores"))).andExpect(content().string(org.hamcrest.Matchers.containsString("Seguindo"))).andExpect(content().string(org.hamcrest.Matchers.containsString("1.234")));}
@Test void rendersBrandedLogin()throws Exception{mvc.perform(get("/login")).andExpect(status().isOk()).andExpect(view().name("login")).andExpect(content().string(org.hamcrest.Matchers.containsString("/images/elyon-logo.png")));}
@Test @WithMockUser void rendersTrafficModuleSafelyWithoutMetaCredentials()throws Exception{mvc.perform(get("/trafego")).andExpect(status().isOk()).andExpect(view().name("traffic")).andExpect(content().string(org.hamcrest.Matchers.containsString("Gestão de Tráfego"))).andExpect(content().string(org.hamcrest.Matchers.containsString("CONFIGURAÇÃO PENDENTE")));}
@Test @WithMockUser void paginatesRecentAudits()throws Exception{for(int i=0;i<9;i++){Audit a=new Audit();a.username="pagina"+i;a.status="CONCLUÍDO";repo.save(a);}mvc.perform(get("/")).andExpect(status().isOk()).andExpect(content().string(org.hamcrest.Matchers.containsString("Próxima"))).andExpect(content().string(org.hamcrest.Matchers.containsString("Página 1 de")));}
@Test @WithMockUser void rejectsEmptyEvidenceWithoutCallingAi()throws Exception{mvc.perform(multipart("/analisar").param("username","@teste").param("segment","Loja").param("goal","Vender").param("mode","manual").with(org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf())).andExpect(status().is3xxRedirection()).andExpect(flash().attributeExists("error"));}
}
